#include "../Source/Processor.h"
#include <iostream>
#define check(x) do{if(!(x)){std::cerr<<__LINE__<<": " #x "\n";std::abort();}}while(false)
using namespace composer;
std::string project(int channel=16,int count=1){Composition c;c.id="preview-test";c.endTick={1920};c.tempos={{{0},500000}};c.meters={{{0},4,4}};c.keys={{{0},0,Scale::naturalMinor}};Track t;t.id=1;t.name="Preview";t.channel=channel;t.role=channel==10?Role::drums:Role::bass;for(int i=0;i<count;++i)t.notes.push_back({Id(i+2),count==1?60:i,100,{0},{240}});t.controls={{1000,{120},64,127},{1001,{960},64,0}};c.tracks={t};ProjectState p;p.activeMode=ProjectMode::composer;p.composition=c;auto encoded=encodeProjectJson(p);check(encoded);return encoded.json;}
int main(){juce::ScopedJuceInitialiser_GUI init;
 for(int size:{32,64}){auto a=std::make_unique<Processor>(),b=std::make_unique<Processor>();const auto state=project();for(auto* p:{a.get(),b.get()}){p->prepareToPlay(48000,size);check(p->restoreStateInformation(state.data(),int(state.size())));p->play=true;}b->audition=false;juce::AudioBuffer<float> audio(2,size),muted(2,size);juce::MidiBuffer midi,ref;midi.ensureSize(32768);ref.ensureSize(32768);double early=0,sustained=0,late=0;
  for(int frame=0;frame<64000;frame+=size){a->processBlock(audio,midi);b->processBlock(muted,ref);check(midi.data==ref.data);for(int s=0;s<size;++s){auto v=audio.getSample(0,s);check(std::isfinite(v)&&std::abs(v)<=1&&muted.getSample(0,s)==0);if(frame<10000)early+=std::abs(v);if(frame>=20000&&frame<30000)sustained+=std::abs(v);if(frame>50000)late+=std::abs(v);}}
  check(early>1&&sustained>1&&late==0);a->play=false;a->processBlock(audio,midi);check(audio.getMagnitude(0,size)==0);
 }
 for(int channel:{1,10,16}){auto p=std::make_unique<Processor>();auto state=project(channel,128);p->prepareToPlay(48000,64);check(p->restoreStateInformation(state.data(),int(state.size())));p->play=true;juce::AudioBuffer<float> audio(2,64);juce::MidiBuffer midi;midi.ensureSize(32768);p->processBlock(audio,midi);check(audio.getMagnitude(0,64)>0&&audio.getMagnitude(0,64)<=1);p->play=false;p->processBlock(audio,midi);check(audio.getMagnitude(0,64)==0);p->play=true;p->processBlock(audio,midi);check(audio.getMagnitude(0,64)>0);p->audition=false;p->processBlock(audio,midi);check(audio.getMagnitude(0,64)==0);}
 {auto p=std::make_unique<Processor>();auto state=project(10);p->prepareToPlay(48000,64);check(p->restoreStateInformation(state.data(),int(state.size())));p->play=true;p->audition=false;juce::AudioBuffer<float> audio(2,64);juce::MidiBuffer midi;midi.ensureSize(32768);for(int i=0;i<600;++i)p->processBlock(audio,midi);p->audition=true;p->processBlock(audio,midi);check(audio.getMagnitude(0,64)<.00001f);}
 {PreviewSynth synth;synth.prepare(48000);synth.message(0x90,60,100);for(int i=0;i<100;++i){synth.message(0x99,42,100);synth.message(0x89,42,0);}float energy=0;for(int i=0;i<64;++i)energy+=std::abs(synth.sample());check(energy>0);}
 for(int pedal:{64,66,69}){PreviewSynth synth;synth.prepare(48000);synth.message(0x9f,60,100);synth.message(0xbf,uint8_t(pedal),127);synth.message(0x8f,60,0);double sum=0;for(int i=0;i<64;++i)sum+=std::abs(synth.sample());check(sum>0);synth.message(0x9f,60,100);synth.message(0x8f,60,0);sum=0;for(int i=0;i<64;++i)sum+=std::abs(synth.sample());check(sum>0);synth.message(0xbf,uint8_t(pedal),0);for(int i=0;i<64;++i)check(synth.sample()==0);}
 {PreviewSynth synth;synth.message(0xbf,66,127);synth.message(0x9f,60,100);synth.message(0x8f,60,0);check(synth.sample()==0);synth.message(0x9f,60,100);synth.message(0xbf,7,0);check(synth.sample()==0);synth.message(0xbf,7,127);check(synth.sample()!=0);synth.message(0xbf,120,0);check(synth.sample()==0);}
 {auto p=std::make_unique<Processor>();auto state=project();check(p->restoreStateInformation(state.data(),int(state.size())));std::unique_ptr<juce::AudioProcessorEditor> editor(p->createEditor());juce::ToggleButton* sound=nullptr;for(int i=0;i<editor->getNumChildComponents();++i)if(auto* toggle=dynamic_cast<juce::ToggleButton*>(editor->getChildComponent(i)))if(toggle->getButtonText()=="SOUND")sound=toggle;check(sound&&sound->isVisible()&&sound->isEnabled());sound->setToggleState(false,juce::dontSendNotification);sound->onClick();check(!p->audition);editor.reset();editor.reset(p->createEditor());sound=nullptr;for(int i=0;i<editor->getNumChildComponents();++i)if(auto* toggle=dynamic_cast<juce::ToggleButton*>(editor->getChildComponent(i)))if(toggle->getButtonText()=="SOUND")sound=toggle;check(sound&&!sound->getToggleState());sound->setToggleState(true,juce::dontSendNotification);sound->onClick();check(p->audition);}
 std::cout<<"Composer basic preview,32/64samples,sustain/stop/mute,dense channels and unchanged MIDI passed\n";
}
